package com.fixflow.mall.api;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.service.OrderService;
import com.fixflow.mall.service.UserService;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class MallControllerTest {

    @Mock
    private UserService userService;

    @Mock
    private OrderService orderService;

    @InjectMocks
    private MallController mallController;

    @Test
    @DisplayName("正向测试：验证getOrder方法在正常输入下返回正确的MallOrder")
    void testGetOrderWithValidId() {
        Long orderId = 1L;
        MallOrder expectedOrder = new MallOrder();
        when(orderService.findOrder(orderId)).thenReturn(expectedOrder);

        MallOrder result = mallController.getOrder(orderId);

        assertNotNull(result);
        assertEquals(expectedOrder, result);
        verify(orderService).findOrder(orderId);
    }

    @Test
    @DisplayName("边界测试：验证原来导致异常的输入现在不再抛出异常")
    void testGetOrderDoesNotThrowExceptionForValidInput() {
        Long orderId = 2L;
        MallOrder mockOrder = new MallOrder();
        when(orderService.findOrder(orderId)).thenReturn(mockOrder);

        assertDoesNotThrow(() -> {
            mallController.getOrder(orderId);
        });
        verify(orderService).findOrder(orderId);
    }

    @Test
    @DisplayName("空值/null处理测试：验证当订单不存在时返回null")
    void testGetOrderReturnsNullWhenOrderNotFound() {
        Long orderId = 3L;
        when(orderService.findOrder(orderId)).thenReturn(null);

        MallOrder result = mallController.getOrder(orderId);

        assertNull(result);
        verify(orderService).findOrder(orderId);
    }
}
